#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <cassert>
#include <fstream>
#include <iostream>
using namespace hb::gpu;using Json=nlohmann::json;
static std::vector<std::uint8_t> decode(const std::string& text){const std::string chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";std::vector<std::uint8_t> out;unsigned value=0,bits=0;for(char c:text){if(c=='=')break;const auto at=chars.find(c);if(at==std::string::npos)throw std::runtime_error("base64");value=(value<<6)|static_cast<unsigned>(at);bits+=6;if(bits>=8){bits-=8;out.push_back(static_cast<std::uint8_t>(value>>bits));}}return out;}
template<class F>static void rejects(F fn){bool rejected=false;try{fn();}catch(const std::exception&){rejected=true;}assert(rejected);}
int main(int argc,char** argv){assert(argc==2);std::ifstream file(argv[1]);Json cases;file>>cases;Device gpu;SceneRenderer renderer(gpu,16,16);auto mesh=renderer.createMesh({{{-1,-1,.4f}},{{1,-1,.4f}},{{1,1,.4f}},{{-1,1,.4f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;material.doubleSided=true;SceneFrame frame;frame.ambient={0,0,0,1};Json rows=Json::array();
 for(const auto& test:cases){const auto& p=test.at("packet");const auto kind=test.at("kind").get<std::string>();const bool volume=kind=="volumetexture",cube=kind=="cubemap",flat=kind=="texture2d";std::vector<SceneRenderer::TextureMipLevel> levels;for(const auto& l:p.at("mipLevels"))levels.push_back({l.at("width"),l.at("height"),decode(l.at("rgbaBase64")),l.value("layers",1u)});auto texture=renderer.createDataTexture(p.at("width"),p.at("height"),decode(p.at("rgbaBase64")),4,false,p.at("layers"),false,!volume&&!cube&&!flat,cube?"cube":volume?"volume":"2d",false,false,levels);
  std::vector<SceneRenderer::TextureRegion> patches;std::uint64_t bytes=0;for(const auto& r:test.at("regionPacket").at("patches")){patches.push_back({r.at("level"),r.at("x"),r.at("y"),r.at("z"),r.at("width"),r.at("height"),r.at("depth"),decode(r.at("rgbaBase64"))});bytes+=patches.back().rgba.size();}const auto updates=renderer.textureRegionUpdates(),sent=renderer.textureRegionUpdateBytes(),storage=texture.storageBytes();
  const std::string coord=flat?"float2(hbParameters[0],hbParameters[1])":"float3(hbParameters[0],hbParameters[1],hbParameters[2])";auto program=renderer.createProgram(std::string(flat?"Texture2D":cube?"TextureCube":volume?"Texture3D":"Texture2DArray")+" tex:register(t8);SamplerState samp:register(s0);StructuredBuffer<float> hbParameters:register(t7);","base=tex.SampleLevel(samp,"+coord+",hbParameters[3]);",{0,0,0,0});
  const auto render=[&](const Json& s){const auto c=s.at("coordinate").get<std::vector<float>>();renderer.setProgramParameters(program,{c[0],c[1],c[2],s.at("level").get<float>()});renderer.begin(frame);renderer.draw(mesh,identity,identity,material,{}, {},0,0,&program,{&texture},{0});const auto pixels=renderer.readPixels();std::array<int,4> result{};for(int c=0;c<4;++c)result[c]=pixels[(8*16+8)*4+c];return result;};
  const auto before=render(test.at("samples")[0]);for(int bad=0;bad<6;bad++){auto broken=patches;auto& b=broken.back();if(bad==0)b.level=99;else if(bad==1)b.x=UINT_MAX;else if(bad==2)b.z=UINT_MAX;else if(bad==3)b.width=0;else if(bad==4)b.rgba.pop_back();else b.depth=UINT_MAX;rejects([&]{renderer.updateTextureRegions(texture,broken);});assert(renderer.textureRegionUpdates()==updates&&renderer.textureRegionUpdateBytes()==sent);assert(render(test.at("samples")[0])==before);}
  const auto uploads=renderer.uploads();renderer.updateTextureRegions(texture,patches);assert(renderer.uploads()==uploads);assert(renderer.textureRegionUpdates()==updates+patches.size());assert(renderer.textureRegionUpdateBytes()==sent+bytes);assert(texture.storageBytes()==storage);Json samples=Json::array();for(const auto& s:test.at("samples")){const auto rgba=render(s);for(int c=0;c<4;c++){const int linearByte=s.at("expected")[c];const double linear=linearByte/255.0;const int expected=c==3?linearByte:static_cast<int>(std::lround(255.0*(linear<=.0031308?linear*12.92:1.055*std::pow(linear,1.0/2.4)-.055)));assert(std::abs(rgba[c]-expected)<3);}samples.push_back(rgba);}rows.push_back({{"kind",kind},{"samples",samples},{"regions",patches.size()},{"sentBytes",bytes},{"fullBytes",storage},{"invalidBatchRejected",6},{"textureAllocations",0}});
 }
 std::cout<<Json{{"passed",true},{"actualD3D11",true},{"rows",rows}};
}
